css:
/* Live locations: the map and the cards are the same `locations-map` widget.
   The list is a horizontal rail; arrows only page it. */
[data-bz-section="location-rail"] > .bz-section { padding-block: 120px }
[data-bz-section="location-rail"] .bz-block { padding-block: 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-head-col"] .bz-block + .bz-block { padding-block-start: 18px }
[data-bz-section="location-rail"] h2 { font-size: 38px; margin: 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-body"] .bz-text { max-width: 640px }
[data-bz-section="location-rail"] [data-bz-node="lr-body"] p { font-size: 16px; line-height: 1.6; color: var(--body-text); margin: 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-head"] { margin-bottom: 40px }
[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-map {
  width: 100%; aspect-ratio: auto; min-height: 460px;
  background: var(--paper); border: 1px solid var(--line); margin: 0 0 44px;
  border-radius: 0;
}
[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-widget__empty { margin-bottom: 24px }
[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-loclist {
  display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory;
  grid-template-columns: none;
  padding-bottom: 4px;
}
[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-loc {
  flex: 0 0 320px; scroll-snap-align: start;
}
[data-bz-section="location-rail"] [data-bz-node="lr-nav-row"] { margin-block: 20px 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] .bz-btns { margin-block: 0; justify-content: flex-end; gap: 8px }
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] .bz-btn {
  width: 38px; height: 38px; min-height: 0; padding: 0;
  border: 1px solid var(--line); background: var(--card); color: var(--ink);
}
@media (max-width: 640px) {
  [data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-loc { flex-basis: 82vw }
}

js:
/* Arrow scrolling for the location rail. The cards themselves are the live
   locations-map widget; this only pages the overflow container. */
(function () {
  document.querySelectorAll('[data-bz-section="location-rail"]').forEach(function (band) {
    var track = band.querySelector('.bz-loclist');
    if (!track) return;
    function page(dir) {
      var card = track.querySelector('.bz-loc');
      var step = card ? card.offsetWidth + 20 : track.clientWidth;
      track.scrollBy({ left: dir * step, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    }
    ['lr-prev', 'lr-next'].forEach(function (id, i) {
      var host = band.querySelector('[data-bz-node="' + id + '"]');
      var control = host && host.querySelector('a, button');
      if (!control) return;
      control.addEventListener('click', function (event) {
        event.preventDefault();
        page(i === 0 ? -1 : 1);
      });
    });
  });
})();
